SELECT COUNT(*) > 0
  FROM facility_manager fm
  JOIN facility f ON f.facility_id = fm.facility_id
 WHERE fm.facility_id = #{facilityId}
   AND fm.user_id = #{userId}
   AND f.deleted_at IS NULL

SELECT COUNT(*) > 0
  FROM match_participant p
 WHERE p.match_id = #{matchId}
   AND p.user_id = #{userId}
   AND p.participation_status = #{participationStatus}

SELECT r.report_id
  FROM report r
 WHERE r.reporter_user_id = #{reporterUserId}
   AND r.match_id = #{matchId}
   AND r.target_user_id = #{targetUserId}
   AND r.category = #{category}
   AND BINARY r.summary = BINARY #{summary}
   AND r.created_at >= TIMESTAMPADD(SECOND, 0 - #{windowSeconds}, CURRENT_TIMESTAMP)
 ORDER BY r.report_id DESC
 LIMIT 1

SELECT r.report_id AS reportId ,r.match_id AS matchId ,f.name AS facilityName ,m.title AS matchTitle ,target.nickname AS targetName ,reporter.nickname AS reporterName ,r.category AS category ,r.status AS status ,r.created_at AS createdAt ,r.resolution AS resolution FROM report r LEFT JOIN social_match m ON m.match_id = r.match_id LEFT JOIN facility f ON f.facility_id = m.facility_id LEFT JOIN app_user target ON target.user_id = r.target_user_id LEFT JOIN app_user reporter ON reporter.user_id = r.reporter_user_id
r.status = #{status}
ORDER BY r.created_at DESC, r.report_id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE report
   SET status = #{targetStatus},
       reviewed_by = #{reviewedBy}
 WHERE report_id = #{reportId}
   AND status = #{expectedStatus}
   AND status = '접수'
